import {playAssistedAction} from './companion-ai.js';
import {lifeView as drawLife,cryptView as drawCrypt,templePanel as drawTemple} from './life-view.js';
import * as L from './life-engine.js';
import {PATRONS,PROFESSIONS,ROOMS,SPELLS} from './life-data.js';
import * as E from './engine.js';
import {REALMS,PLACES,QUESTS,ITEMS,CLASSES,NPCS,BOOKS} from './world.js';
const KEY='moonveil-universe-play-v1',app=document.getElementById('app'),modal=document.getElementById('modal'),body=document.getElementById('modalBody');
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const glyph={sword:'⚔',spark:'✧',flask:'♜',diamond:'◇',leaf:'❧',book:'▤'};
let referenceRecords=[],referenceLegal='',referenceSearch='';let state=null,library=[],sceneFrame=0,codexFilter='all',codexSearch='',calling='Vanguard',chat=[],toastTimer,audio=null,ambient=[],disk=localStorage.getItem(KEY),loadError='';
try{if(disk)state=E.validateGame(JSON.parse(disk));}catch(error){loadError='Your saved file needs repair. It has been kept unchanged. Export it before starting another character.';}
try{const r=await fetch('assets/library/library-manifest.json');if(r.ok)library=(await r.json()).assets||[];}catch{}
try{const r=await fetch('data/srd-library.json');if(r.ok){const d=await r.json();referenceRecords=d.records;referenceLegal=d.legal;}}catch{}
try{const response=await fetch('assets/generated-manifest.json');if(response.ok)library.push(...(await response.json()).assets);}catch{}
const fixLabel=t=>t.replaceAll('â€™','’').replaceAll('â€“','–');
const file=(hint)=>library.find(a=>a.label.toLowerCase().includes(hint.toLowerCase()))?.path||'assets/moonveil-realms.png';
const art={cthulhu:'assets/moonveil-cthulhu.png',nodens:'assets/moonveil-nodens.png',gateway:file('Emerald Gateway'),workshop:file('Candlelit'),mist:file('Misty Treehouse'),tomb:file('Tomb of Diderius'),garden:file('Hidden Ridge'),forest:file('Portal to'),waterfall:file('waterfall'),astral:file('Astral Spelljammer'),forge:file('Hall of Frozen')};
const current=()=>PLACES.find(p=>p.id===state.location),realm=()=>REALMS.find(r=>r.id===current().realm);
const picture=p=>library.find(a=>a.id===state?.artAssignments?.[p.id])?.path||art[p.art]||'assets/moonveil-realms.png';
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4000);}
function saveCandidate(candidate){const existing=localStorage.getItem(KEY);if(existing!==disk)throw Error('Another tab changed this save. Reload to use the latest progress.');candidate.revision++;const serialized=JSON.stringify(candidate);localStorage.setItem(KEY,serialized);disk=serialized;state=candidate;}
function apply(fn,notice){const previousLocation=state.location,previousView=state.view,next=E.clone(state);fn(next);E.validateGame(next);saveCandidate(next);if(notice)toast(notice);render();if(previousLocation!==state.location||previousView!==state.view)window.scrollTo({top:0,behavior:'instant'});if(state.dialogue)document.querySelector('.speech-bubble')?.scrollIntoView({behavior:'smooth',block:'center'});tone();}
function showModal(html){body.innerHTML=html;if(!modal.open)modal.showModal();}
function closeModal(){modal.close();}
const button=(text,action,extra='',cls='')=>`<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
function topbar(landing=false){return `<header class="topbar"><button class="brand icon-button" data-action="home" aria-label="Moonveil home"><span class="moon-mark">☾</span><span><strong>MOONVEIL</strong><small>U N I V E R S E</small></span></button>${landing?'':`<nav class="topnav" aria-label="Game navigation">${[['journey','Journey'],['atlas','World Atlas'],['life','World & Sheets'],['codex','Visual Codex'],['battle','War Table'],['character','Character'],['inventory','Inventory'],['guide','Game Master']].map(([v,label])=>button(label,'view',`data-view="${v}"`,state.view===v?'active':'')).join('')}</nav>`}<div class="header-actions">${state?'<span class="save-indicator">● Progress saved</span>':''}${button(state?.sound?'♫ Sound on':'♫ Sound off','sound','','sound-button ghost')}${button('⚙','settings','aria-label="Settings and saves"','icon-button')}</div></header>`;}
function landing(){app.innerHTML=`<div class="landing">${topbar(true)}<section class="landing-hero"><div class="landing-copy"><span class="pill"><span class="dot"></span> Four realms. One unfolding story.</span><span class="eyebrow" style="margin-top:28px">A cinematic tabletop adventure</span><h1>Every world<br>begins with <em>you.</em></h1><p>Step through the veil. Find your companions, follow impossible roads, and leave your mark on a living multiverse.</p><div class="landing-actions">${button(state?'Continue your journey →':'Create your character →',state?'continue':'create','','primary')}${button('Explore the realms','preview-realms','','ghost')}</div><div class="landing-meta"><span>◇ CINEMATIC STORIES</span><span>⚔ TACTICAL ENCOUNTERS</span><span>✧ YOUR CHOICES MATTER</span></div>${loadError?`<p class="notice">${esc(loadError)} ${button('Export preserved save','export-raw')}</p>`:''}</div></section><section class="section-wrap" id="realms"><div class="section-head"><div><span class="eyebrow">Beyond the familiar</span><h2>A universe of possibilities.</h2></div><small>Begin anywhere. Return through the Nexus.</small></div><div class="realm-grid">${REALMS.map((r,i)=>`<button class="realm-card" data-action="realm-preview" data-realm="${r.id}" style="background-image:url('${picture(PLACES.find(p=>p.id===r.hub))}');background-position:center"><span class="realm-number">0${i+1}</span><div><span class="eyebrow">${i===0?'Under a broken moon':i===1?'Where the forest remembers':'Beyond the edge of stars'}</span><h3>${r.name}</h3><p>${r.mood}</p></div></button>`).join('')}</div></section><footer class="landing-footer">MOONVEIL UNIVERSE · A homebrew fantasy adventure · Original campaign artwork preserved · Your progress stays on this browser</footer></div>`;}
function activeQuest(){return QUESTS.find(q=>state.quests[q.id]&&state.quests[q.id].phase!=='complete');}
function sidebar(){const h=state.hero,q=activeQuest();return `<aside class="sidebar"><div class="hero-head"><div class="hero-avatar">${h.name[0].toUpperCase()}</div><div><h3>${esc(h.name)}</h3><p>${esc(h.ancestry)} · ${h.className} · Level ${h.level}</p></div></div><div class="stat-line"><span>Hit points</span><span>${h.hp} <small>/ ${h.maxHp}</small></span></div><div class="health-track"><div style="width:${h.hp/h.maxHp*100}%"></div></div><div class="mini-stats"><div><strong>${h.ac}</strong><small>Armor class</small></div><div><strong>${h.slots}</strong><small>Focus</small></div><div><strong>${h.gold}</strong><small>Gold</small></div></div><div class="secondary-actions">${button('Character sheet','view','data-view="character"')}${button('Inventory','view','data-view="inventory"')}</div><section class="section-divider"><span class="eyebrow">Your next chapter</span><div class="quest-mini"><strong>${q?esc(q.name):'A road yet unwritten'}</strong><p>${q?esc(E.guide(state,'next')):'Explore a realm and speak to its keeper.'}</p></div></section><section class="section-divider"><span class="eyebrow">Traveling companion</span><div class="companion-card"><div class="construct-icon">⚙</div><div><strong>Orison <span class="online-dot"></span></strong><p>Waybound construct · ${state.companion.charge}/3 charge<br>${state.companion.enabled?'Autonomous scouting enabled':'Following quietly'}</p>${button(state.battle?.status==='active'?'Project shield':'Scout ahead','companion')}</div></div></section><section class="section-divider"><span class="eyebrow">The world moves</span><div class="world-log">${state.events.slice(0,5).map(e=>`<div class="log-row"><span class="log-dot"></span><span>${esc(e.text)}</span></div>`).join('')}</div></section><p class="chapter-footer">CHAPTER ${String(state.chapter).padStart(2,'0')} · ${state.visited.length} PLACES DISCOVERED</p></aside>`;}
function choice(index,title,detail,action,attrs=''){return `<button class="choice" data-action="${action}" ${attrs}><span class="choice-index">${index}</span><span><strong>${title}</strong>${detail?`<small>${detail}</small>`:''}</span><span class="chevron">→</span></button>`;}
function journey(){const p=current(),r=realm(),q=QUESTS.find(q=>q.giver===p.id),siteQuest=QUESTS.find(q=>q.site===p.id);let choices='';let n=1;
if(state.loot)choices+=choice(n++,'Collect the recovered relic','Add encounter loot to your inventory.','loot');
else if(state.battle?.status==='active')choices+=choice(n++,'Return to the encounter','Your positions and current turn are preserved.','view','data-view="battle"');
else{
if(q&&!state.quests[q.id])choices+=choice(n++,'Speak to '+esc(p.speaker),'A local story is waiting for you.','talk');
else if(q&&state.quests[q.id]?.phase==='return')choices+=choice(n++,'Return the relic to '+esc(p.speaker),'Complete '+esc(q.name)+' · '+q.reward+' gold reward','complete',`data-quest="${q.id}"`);
else choices+=choice(n++,'Speak to '+esc(p.speaker),'Hear what this place remembers.','talk');
if(siteQuest&&p.id!=='lich-crypt'&&state.quests[siteQuest.id]?.phase==='accepted')choices+=choice(n++,'Confront the guardian','Open the tactical war table.','engage');
choices+=p.neighbors.map(id=>{const target=PLACES.find(x=>x.id===id);return choice(n++,p.id==='nexus'?'Enter '+(REALMS.find(x=>x.hub===id)?.name||target.name):'Travel to '+esc(target.name),target.kind+' · A connected route','travel',`data-to="${id}"`)}).join('');}
const frames=[{name:'The approach',src:picture(p)},{name:'A world in motion',src:art.gateway},{name:'The unseen',src:p.realm==='astral'?art.astral:p.realm==='verdant'?art.waterfall:art.mist},{name:'Your next choice',src:picture(p)}];
return `<div class="location-row"><div class="location-title"><div class="breadcrumb">${esc(r.name)} <span>/</span> ${p.kind}</div><h2>${p.name}</h2></div><div class="world-time">${['Moonrise','Deep night','First light','Silver dusk'][Math.floor(state.tick/6)%4]}<br><span class="muted">Day ${1+Math.floor(state.tick/24)} · World pulse ${state.tick}</span></div></div><div class="cinema-stage"><img src="${frames[sceneFrame].src}" alt="Original campaign scene artwork used for ${esc(p.name)}"><div class="cinema-label"><span class="online-dot"></span> CINEMATIC JOURNEY</div><span class="scene-counter">${sceneFrame+1} / 4</span>${sceneLayers()}${state.dialogue?`<div class="speech-bubble"><div class="speaker">${esc(p.speaker)}</div><p>${esc(state.dialogue.step===0?dialogueFirst(p,q):dialogueSecond(p,q))}</p>${button(state.dialogue.step===0?'Continue →':'Close conversation','dialogue-next')}</div>`:`<div class="scene-caption"><span class="eyebrow">${p.id==='nexus'?'The roads between worlds':'Your story continues'}</span><h3>${p.name}</h3><p>${p.description}</p></div>`}</div><div class="filmstrip">${frames.map((f,i)=>`<button class="film-frame ${sceneFrame===i?'active':''}" data-action="frame" data-frame="${i}" aria-label="Scene frame ${i+1}: ${f.name}"><img src="${f.src}" alt="" loading="lazy"><span>0${i+1} &nbsp; ${f.name}</span></button>`).join('')}</div><section class="story-section">${state.director?`<div class="director-bubble"><span class="eyebrow">${esc(state.director.speaker)}</span><p>${esc(state.director.text)}</p>${button('Continue the story','dismiss-director')}</div>`:''}<span class="eyebrow">The story is yours</span><h3>${state.dialogue?'A voice in the veil':'What will you do?'}</h3><p>${state.dialogue?'Choose how your story moves forward.':E.guide(state,'next')}</p><div class="action-list">${state.dialogue&&q&&!state.quests[q.id]?choice('✧','Accept: '+q.name,q.summary,'accept',`data-quest="${q.id}"`):''}${choices}</div><div class="secondary-actions">${button('❧ Quests, professions & temples','view','data-view="life"')}${button('◇ Explore the area','explore')}${button('⚙ Ask Orison to scout','companion')}${button('☾ Rest & recover','rest')}${['lanternfall','glasshaven','starharbor'].includes(p.id)?button('Visit the market','shop'):''}</div></section>`;}
function dialogueFirst(p,q){const phase=q&&state.quests[q.id]?.phase;if(phase==='complete')return 'The light you brought back is still burning. You will always be welcome here, traveler.';if(phase==='return')return 'You found it! Let us put the relic back where it belongs.';if(phase==='accepted')return 'Our hope travels with you. Follow the road to the guardian, and let Orison watch your back.';return p.line;}
function dialogueSecond(p,q){if(q&&!state.quests[q.id])return q.summary;if(q&&state.quests[q.id]?.phase==='complete')return 'You have given this place something worth keeping. The road will remember your kindness.';if(q)return 'Follow the road beyond the city. Orison can help you find the way. Return when you have the relic.';return p.id==='nexus'?'The Marches, the Expanse, the Reach. Each has a keeper who needs help. Rest here whenever the road becomes too hard.':'We can move when you are ready. I will keep the lantern burning.';}
function atlas(){const p=current();return `<div class="view-header"><span class="eyebrow">The multiverse</span><h2>Every road leads somewhere.</h2><p>Select a place to inspect its route. A preview never moves your character.</p></div><div class="atlas-map"><svg viewBox="0 0 100 100" preserveAspectRatio="none">${PLACES.flatMap(a=>a.neighbors.map(id=>{const b=PLACES.find(p=>p.id===id);return `<line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}"/>`})).join('')}</svg>${PLACES.map(a=>`<button class="map-node ${a.id===p.id?'current':''}" style="left:${a.x}%;top:${a.y}%" data-action="inspect-place" data-place="${a.id}"><strong>${a.name}</strong><small>${state.visited.includes(a.id)?'◇ Discovered':'✧ Unexplored'}</small></button>`).join('')}</div><div class="atlas-key"><span>◇ Current location: ${p.name}</span><span>${state.visited.length} / ${PLACES.length} places discovered</span></div><h3>Roads from here</h3>${p.neighbors.map(id=>{const a=PLACES.find(p=>p.id===id);return `<div class="route-card"><div><strong>${a.name}</strong><p>${a.kind} · ${REALMS.find(r=>r.id===a.realm).name}</p></div>${button('Travel →','travel',`data-to="${id}"`)}</div>`}).join('')}`;}
function inventory(){return `<div class="view-header"><span class="eyebrow">What you carry</span><h2>Inventory & equipment</h2><p>${state.hero.gold} gold · Equipment, books, supplies and recovered quest objects.</p></div><div class="inventory-list">${state.inventory.filter(row=>row.quantity>0).map(row=>{const i=ITEMS.find(i=>i.id===row.id);return `<div class="inventory-row"><div class="item-glyph">${glyph[i.icon]}</div><div class="inventory-copy"><h3>${i.name} <small>×${row.quantity}</small></h3><p>${i.description}</p></div>${i.kind==='Ritual scroll'?button('Read ritual','view','data-view="life"'):i.id==='potion'?button('Drink','potion'):i.id==='ward'?button('Activate','use-ward',state.battle?.status==='active'&&!state.battle.actionSpent?'':'disabled'):i.kind==='Book'?button('Read','read-book',`data-book="${i.id}"`):button('Inspect','inspect-item',`data-item="${i.id}"`)}</div>`}).join('')}</div><div class="notice">Item symbols are interface icons. Original scene artwork is shown where verified; standalone item portraits have not yet been reliably matched to every record.</div>`;}
function character(){const h=state.hero;return `<div class="view-header"><span class="eyebrow">Your place in the story</span><h2>${esc(h.name)}</h2><p>${esc(h.ancestry)} · ${h.className} · ${esc(h.pronouns)} · Level ${h.level}</p></div><div class="panel"><div class="mini-stats">${[['HP',h.hp+'/'+h.maxHp],['Armor class',h.ac],['Focus',h.slots+'/'+h.maxSlots],['Experience',h.xp],['Gold',h.gold],['Places',state.visited.length]].map(([a,b])=>`<div><strong>${b}</strong><small>${a}</small></div>`).join('')}</div></div><section class="story-section"><h3>Abilities & calling</h3><p>${CLASSES[h.className].focus}. These lightweight homebrew callings let you begin immediately. Comprehensive official character creation is not yet implemented.</p><div class="inventory-list"><div class="inventory-row"><div class="item-glyph">⚔</div><div class="inventory-copy"><h3>Moonsteel Strike</h3><p>+5 to hit · 1d8 + 3 damage · Melee · One action</p></div></div><div class="inventory-row"><div class="item-glyph">✧</div><div class="inventory-copy"><h3>Arcane Bolt</h3><p>+5 to hit · 1d10 force · Line of sight required · One action</p></div></div><div class="inventory-row"><div class="item-glyph">◇</div><div class="inventory-copy"><h3>Brace</h3><p>+2 AC until the next turn · One action</p></div></div></div></section><section class="story-section"><h3>Quest journal</h3>${QUESTS.map(q=>`<div class="route-card"><div><strong>${q.name}</strong><p>${q.summary}</p><small>${state.quests[q.id]?.phase||'Not yet accepted'}</small></div>${button('Show route','inspect-place',`data-place="${state.quests[q.id]?.phase==='return'?q.giver:q.site}"`)}</div>`).join('')}</section>${button('Create another character','create','','ghost')}`;}
function codex(){let entries=library.filter(a=>(codexFilter==='all'||a.category===codexFilter)&&fixLabel(a.label).toLowerCase().includes(codexSearch.toLowerCase()));return `<div class="view-header"><span class="eyebrow">The visual archive</span><h2>A universe, remembered.</h2><p>${library.length} artwork files · 146 preserved originals and new generated domain illustrations. Original names and source IDs are retained.</p></div><div class="codex-tools"><input id="codexSearch" placeholder="Search the visual archive…" aria-label="Search the visual archive" value="${esc(codexSearch)}"><select id="codexFilter" aria-label="Filter artwork category">${['all',...new Set(library.map(a=>a.category))].map(c=>`<option value="${c}" ${c===codexFilter?'selected':''}>${c==='all'?'All artwork':c[0].toUpperCase()+c.slice(1)}</option>`).join('')}</select>${button('Books & lore','read-book','data-book="atlas"')}</div><div class="codex-grid">${entries.map(a=>`<button class="codex-card" data-action="inspect-art" data-art="${a.id}"><img src="${a.path}" alt="${esc(fixLabel(a.label))}" loading="lazy"><div class="card-info"><span class="eyebrow">${esc(a.category)}</span><h3>${esc(fixLabel(a.label))}</h3><p>${a.origin==='generated'?'New Moonveil interpretation':'Original campaign artwork'} · View full image</p></div></button>`).join('')}</div>${entries.length?'':'<p>No matching artwork. Try another search.</p>'}<div class="section-divider"><h3>People of Moonveil</h3><div class="codex-grid">${NPCS.map(n=>`<button class="codex-card" data-action="inspect-place" data-place="${n.home}"><img src="${picture(PLACES.find(p=>p.id===n.home))}" alt="Location illustration for ${n.name}" loading="lazy"><div class="card-info"><h3>${n.name}</h3><p>${n.role} · Location illustration; portrait not yet assigned.</p></div></button>`).join('')}</div></div>`;}
function battle(){const b=state.battle;if(!b)return `<div class="view-header"><span class="eyebrow">Tactical encounters</span><h2>The war table awaits.</h2><p>Accept a realm keeper’s quest, travel to its encounter site, then challenge the guardian. Your positions and turn save automatically.</p></div>${button('Find your next step','view','data-view="journey"','primary')}`;const h=b.units.find(u=>u.id==='hero');return `<div class="view-header"><span class="eyebrow">Tactical encounter · ${current().name}</span><h2>${b.status==='won'?'The way is clear.':b.status==='lost'?'The light holds.':'Make your move.'}</h2><p>Round ${b.round} · 5 feet per square · Walls block movement and ranged attacks.</p></div>${b.status==='won'?`<div class="victory"><h3>Victory</h3><p>The guardian falls silent. The relic is yours to recover.</p>${button('Collect loot & return to the story','loot','','primary')}</div>`:b.status==='lost'?`<div class="victory"><h3>Orison has you.</h3><p>Your companion can return you to sanctuary. Your accepted quests remain.</p>${button('Recover at the Nexus','retreat','','primary')}</div>`:''}<div class="battle-layout"><div><div class="battle-board" style="background-image:linear-gradient(#0a101855,#0a101855),url('${library.find(a=>a.id===state.battleArtAssignments?.[state.location])?.path||(current().id==='drowned-causeway'?art.cthulhu:file('Chapter11 Diderius'))}')" role="group" aria-label="8 by 8 tactical battlefield">${Array.from({length:64},(_,i)=>{const x=i%8,y=Math.floor(i/8),u=b.units.find(t=>t.x===x&&t.y===y&&t.hp>0),wall=b.terrain.includes(x+','+y);return `<button class="battle-cell ${wall?'blocked':''} ${u?.side||''} ${u?.id===b.selected?'target':''}" data-action="cell" data-x="${x}" data-y="${y}" ${u?`data-unit="${u.id}"`:''} aria-label="${u?esc(u.name)+', '+u.hp+' HP':wall?'Wall':'Square '+String.fromCharCode(65+x)+(y+1)}"><span class="coordinate">${String.fromCharCode(65+x)}${y+1}</span>${u?(u.side==='hero'?'◆':'♟'):wall?'▨':''}${u?`<span class="unit-hp"><i style="width:${u.hp/u.maxHp*100}%"></i></span>`:''}</button>`}).join('')}</div><div class="battle-log" aria-live="polite">${state.events.filter(e=>['combat','companion','quest'].includes(e.kind)).slice(0,8).map(e=>`<p>${esc(e.text)}</p>`).join('')}</div></div><aside class="battle-controls"><h3>${esc(state.hero.name)}</h3><div class="battle-status">HP ${h.hp}/${h.maxHp} · AC ${h.ac}<br>Action: ${b.actionSpent?'spent':'ready'} · Move: ${b.movement*5} ft<br>Target: ${esc(b.units.find(u=>u.id===b.selected)?.name||'Select an enemy')}</div>${button('✧ Arcane Bolt','attack','data-kind="bolt" '+(b.actionSpent||b.status!=='active'?'disabled':''))}${button('⚔ Moonsteel Strike','attack','data-kind="melee" '+(b.actionSpent||b.status!=='active'?'disabled':''))}${button('Activate wardstone ('+E.quantity(state,'ward')+')','use-ward',b.status!=='active'||b.actionSpent||E.quantity(state,'ward')<1?'disabled':'')}${button('◇ Brace / defend','guard',b.actionSpent||b.status!=='active'?'disabled':'')}${button('♜ Healing Draught ('+E.quantity(state,'potion')+')','potion',b.actionSpent||b.status!=='active'?'disabled':'')}${button('⚙ Orison: shield ('+state.companion.charge+')','companion',b.status!=='active'?'disabled':'')}${SPELLS.map(sp=>button(sp.name+' · 1 focus','cast-spell',`data-spell="${sp.id}" ${b.actionSpent||b.status!=='active'||state.hero.slots<1?'disabled':''}`)).join('')}<p class="muted">Focus ${state.hero.slots}/${state.hero.maxSlots} · Frost Sigil → next-turn Storm Arc triggers Shatter. Homebrew spells; details in World & Sheets.</p>${button('Orison: auto-play my action','assisted-action',b.actionSpent||b.status!=='active'||!state.companion.enabled?'disabled':'')}<p class="muted">Optional local tactical helper: chooses movement and one action. Uses your potions/focus when useful. You still end the turn.</p>${button('End turn →','end-turn',b.status!=='active'?'disabled':'','end-turn')}${button('Retreat to sanctuary','retreat',b.status==='won'?'disabled':'','ghost')}</aside></div>`;}
function guideView(){if(!chat.length)chat=[{who:'guide',text:E.guide(state,'next')}];return `<div class="view-header"><span class="eyebrow">A voice beside the fire</span><h2>Your game master.</h2><p>Ask about your route, quests, combat or companion.</p></div><div class="notice">Local story guide: responds from your actual game state. Autonomous world events and companion behavior are active during play. Live generative AI is not connected.</div><div class="secondary-actions">${button('🎙 Speak a message','listen')}${button('Play together with ChatGPT','assistant-help')}</div><div class="chat-log">${chat.map(m=>`<div class="chat-message ${m.who==='you'?'user':''}"><small>${m.who==='you'?esc(state.hero.name):'THE WAYFINDER'}</small>${esc(m.text)}</div>`).join('')}</div><form class="chat-form" id="chatForm"><input name="message" aria-label="Message the game master" placeholder="What should I do next?" maxlength="500" required><button class="primary">Send →</button></form><div class="secondary-actions">${button('Where do I go next?','guide-question','data-question="next"')}${button('How does combat work?','guide-question','data-question="combat"')}${button('Tell me about Orison','guide-question','data-question="robot"')}</div><section class="story-section"><h3>The living world</h3><p>Keepers, caravans and Orison respond as you explore, travel and rest. World pulses advance with your actions, not while the game is closed.</p>${state.events.filter(e=>e.kind==='world'||e.kind==='companion').slice(0,8).map(e=>`<div class="log-row"><span class="log-dot"></span><p>${esc(e.text)}</p></div>`).join('')}</section>`;}
function render(){if(!state){landing();return;}const views={life:lifeView,journey,atlas,inventory,character,codex,battle,guide:guideView};const view=views[state.view]||journey;app.innerHTML=topbar()+`<div class="game-layout"><main class="main-content fade-in">${view()}${state.view==='journey'&&current().id==='lich-crypt'?cryptView():''}${state.view==='journey'&&current().kind==='Temple'?templePanel(PATRONS.find(p=>p.temple===state.location)):''}${state.view==='codex'?referenceShelf():''}</main>${sidebar()}</div><nav class="mobile-nav" aria-label="Mobile game navigation">${[['journey','☾','Story'],['atlas','◇','Atlas'],['battle','⚔','Battle'],['character','♙','Hero'],['inventory','◇','Items'],['codex','▤','Codex'],['life','❧','World'],['guide','✧','Guide']].map(([v,g,label])=>button(`<span>${g}</span>${label}`,'view',`data-view="${v}"`,state.view===v?'active':'')).join('')}</nav>`;}
function characterForm(){showModal(`<span class="eyebrow">Your first step</span><h2>Who will you become?</h2><p class="muted">A new traveler. A new story. Existing campaign archives stay untouched.</p><form id="characterForm"><div class="form-grid"><label class="full">Character name<input name="name" placeholder="Enter your character’s name" minlength="2" maxlength="32" required autocomplete="off"></label><label>Ancestry<select name="ancestry"><option>Human</option><option>Elf</option><option>Dwarf</option><option>Tiefling</option><option>Dhampir</option><option>Construct</option></select></label><label>Pronouns<select name="pronouns"><option>they/them</option><option>she/her</option><option>he/him</option></select></label><div class="full"><span class="eyebrow">Choose your calling</span><div class="calling-grid">${Object.entries(CLASSES).map(([name,c])=>button(`<span>${name==='Vanguard'?'⚔':name==='Arcanist'?'✧':'◇'}</span><h3>${name}</h3><small>${c.focus}<br>${c.hp} HP · AC ${c.ac}</small>`,'calling',`data-calling="${name}" type="button"`,calling===name?'calling-card selected':'calling-card')).join('')}</div></div></div><div class="form-footer"><p>Your character starts at the Nexus with equipment, three healing draughts, an atlas, and Orison.</p><button class="primary" type="submit">Begin your story →</button></div></form>`);}
function shop(){showModal(`<span class="eyebrow">${current().name} · Market</span><h2>Something for the road.</h2><img class="modal-art" src="${art.workshop}" alt="Original healing potion workshop scene"><p>${state.hero.gold} gold in your purse. Purchases go directly into your inventory.</p><div class="inventory-list">${ITEMS.filter(i=>i.price).map(i=>`<div class="inventory-row"><div class="item-glyph">${glyph[i.icon]}</div><div class="inventory-copy"><h3>${i.name}</h3><p>${i.description}</p></div>${button(i.price+' gold','buy',`data-item="${i.id}" ${state.hero.gold<i.price?'disabled':''}`)}</div>`).join('')}</div>`);}
function inspectPlace(id){const p=PLACES.find(p=>p.id===id),route=E.routeTo(state,id);showModal(`<span class="eyebrow">${p.kind} · Preview only</span><h2>${p.name}</h2><img class="modal-art" src="${picture(p)}" alt="Scene illustration for ${p.name}"><p>${p.description}</p><p class="muted">${route?.length>1?'Route: '+route.map(id=>PLACES.find(p=>p.id===id).name).join(' → '):'You are here.'}</p>${route?.length>1?button('Travel first leg →','travel',`data-to="${route[1]}"`,'primary'):''}`);}
function settings(){showModal(`<span class="eyebrow">Your table, your pace</span><h2>Settings & saved journeys</h2>${state?`<div class="settings-row"><div><strong>Ambient sound</strong><p>Soft synthesized atmosphere and interaction tones. Starts only when enabled.</p></div>${button(state.sound?'On':'Off','sound')}</div><div class="settings-row"><div><strong>Spoken dialogue</strong><p>Uses your browser’s available voice. Text remains visible.</p></div>${button(state.narration?'On':'Off','narration')}</div><div class="settings-row"><div><strong>Autonomous world</strong><p>World events and companion scouting advance with your actions.</p></div>${button(state.autonomy?'On':'Off','autonomy')}</div><div class="settings-row"><div><strong>Orison companion</strong><p>Autonomous scouting, route hints, and active shields.</p></div>${button(state.companion.enabled?'On':'Off','toggle-companion')}</div><div class="secondary-actions">${button('Export save JSON','export')}${button('Import save JSON','import')}${button('Create another character','create')}</div><p class="notice">Progress is saved in this browser. Export a backup before changing devices. This release is single-player and uses homebrew adventure rules.</p>`:`<p>Start a character to enable autosaves and game settings.</p>${button('Import an existing Universe save','import')}`}`);}
function download(value,name){const url=URL.createObjectURL(new Blob([value],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function setAudio(on){if(!on){ambient.forEach(o=>{try{o.stop()}catch{}});ambient=[];audio?.suspend();return;}audio ||= new (window.AudioContext||window.webkitAudioContext)();audio.resume();if(ambient.length)return;for(const hz of [110,164.81,220]){const osc=audio.createOscillator(),gain=audio.createGain();osc.type='sine';osc.frequency.value=hz;gain.gain.value=.012;osc.connect(gain).connect(audio.destination);osc.start();ambient.push(osc);}}
function tone(){if(!state?.sound||!audio)return;const o=audio.createOscillator(),g=audio.createGain();o.frequency.setValueAtTime(660,audio.currentTime);o.frequency.exponentialRampToValueAtTime(330,audio.currentTime+.12);g.gain.setValueAtTime(.025,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.15);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+.16);}
function speak(text){if(!state?.narration||!('speechSynthesis'in window))return;speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.rate=.9;u.pitch=.85;speechSynthesis.speak(u);}
document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;try{
 if(a==='assisted-action'){apply(playAssistedAction);return;}if(a==='inscribe-scroll'){apply(L.inscribeScroll,'Ritual scroll inscribed');return;}if(a==='ritual-node'){apply(s=>L.traceRitual(s,b.dataset.node));return;}if(a==='layer-art'){const asset=library.find(i=>i.id===b.dataset.art);if(!asset||!['left','right'].includes(b.dataset.side))throw Error('Choose verified artwork and a layer slot.');apply(s=>{s.sceneLayers||={};s.sceneLayers[s.location]||={};s.sceneLayers[s.location][b.dataset.side]=asset.id;});closeModal();toast('Reusable image layer placed. Original image unchanged.');return;}if(a==='remove-layer'){apply(s=>{if(s.sceneLayers?.[s.location])delete s.sceneLayers[s.location][b.dataset.side];});return;}if(a==='life-train'){apply(s=>L.train(s,b.dataset.profession),'Profession learned');return;}if(a==='life-gather'){apply(L.gather,'Materials added');return;}if(a==='life-craft'){apply(L.craft,'Crafted and saved');return;}if(a==='life-order'){apply(s=>L.acceptOrder(s,b.dataset.profession),'Commission accepted');return;}if(a==='life-deliver'){apply(s=>L.deliver(s,b.dataset.profession),'Commission complete');return;}if(a==='temple-service'){apply(s=>L.templeService(s,b.dataset.patron,b.dataset.service),'Temple service saved');return;}if(a==='pilgrim-accept'){apply(L.acceptPilgrimage,'Pilgrimage accepted');return;}if(a==='pilgrim-claim'){apply(L.claimPilgrimage,'Pilgrimage complete');return;}if(a==='room-move'){apply(s=>L.moveRoom(s,b.dataset.room));return;}if(a==='room-interact'){apply(L.interactRoom);return;}if(a==='use-ward'){apply(E.useWard,'Wardstone activated');return;}if(a==='cast-spell'){apply(s=>E.castSpell(s,s.battle.selected,b.dataset.spell));return;}if(a==='close-modal'){closeModal();return;}if(a==='create'){characterForm();return;}if(a==='calling'){calling=b.dataset.calling;body.querySelectorAll('[data-calling]').forEach(el=>el.classList.toggle('selected',el.dataset.calling===calling));return;}if(a==='continue'){render();return;}if(a==='home'){landing();return;}if(a==='preview-realms'){document.getElementById('realms')?.scrollIntoView({behavior:'smooth'});return;}if(a==='realm-preview'){const r=REALMS.find(r=>r.id===b.dataset.realm);showModal(`<span class="eyebrow">Beyond the veil</span><h2>${r.name}</h2><img class="modal-art" src="${picture(PLACES.find(p=>p.id===r.hub))}" alt="Realm scene"><p>${r.mood}. A city, a wilderness route, and a connected quest await.</p>${button(state?'Open the Atlas':'Create a character',state?'view':'create',state?'data-view="atlas"':'','primary')}`);return;}if(a==='settings'){settings();return;}if(a==='assistant-help'){assistantHelp();return;}if(a==='listen'){listen();return;}if(a==='dismiss-director'){apply(s=>s.director=null);return;}if(a==='reference'){const r=referenceRecords.find(r=>r.id===b.dataset.record);if(r)showModal('<span class="eyebrow">SRD 5.1 reference · '+esc(r.category)+'</span><h2>'+esc(r.name)+'</h2><pre class="reference-text">'+esc(r.text)+'</pre><small>Reference entry; not automatically implemented as a playable action.</small>');return;}if(a==='reference-legal'){showModal('<h2>SRD attribution</h2><pre class="reference-text">'+esc(referenceLegal)+'</pre>');return;}if(a==='export-raw'){download(disk||'{}','moonveil-preserved-save.json');return;}if(a==='import'){document.getElementById('saveFile').click();return;}
 if(!state)throw Error('Create a character to begin.');
 if(a==='view'){closeModal();apply(s=>s.view=b.dataset.view);window.scrollTo({top:0,behavior:'instant'});return;}if(a==='frame'){sceneFrame=Number(b.dataset.frame);render();tone();return;}if(a==='travel'){closeModal();sceneFrame=0;apply(s=>E.travel(s,b.dataset.to),'Arrived at '+PLACES.find(p=>p.id===b.dataset.to).name);return;}if(a==='talk'){apply(E.talk);speak(dialogueFirst(current(),QUESTS.find(q=>q.giver===state.location)));return;}if(a==='dialogue-next'){apply(s=>{if(s.dialogue.step===0)s.dialogue.step=1;else s.dialogue=null});if(state.dialogue)speak(dialogueSecond(current(),QUESTS.find(q=>q.giver===state.location)));return;}if(a==='accept'){apply(s=>{E.acceptQuest(s,b.dataset.quest);s.dialogue=null},'Quest added to your journal');return;}if(a==='complete'){apply(s=>E.completeQuest(s,b.dataset.quest),'Quest complete. Your reward is recorded.');return;}if(a==='explore'){apply(E.explore,'Your observations were added to the journey.');return;}if(a==='rest'){apply(E.rest,'You and Orison are rested.');return;}if(a==='companion'){apply(E.companionAct,'Orison answers.');return;}if(a==='shop'){shop();return;}if(a==='buy'){apply(s=>E.buy(s,b.dataset.item),'Added to inventory');shop();return;}if(a==='potion'){apply(E.usePotion,'Healing draught consumed');return;}if(a==='engage'){apply(E.beginBattle);return;}if(a==='attack'){apply(s=>E.attack(s,s.battle.selected,b.dataset.kind));return;}if(a==='guard'){apply(E.guard);return;}if(a==='end-turn'){apply(E.endTurn);return;}if(a==='retreat'){apply(E.retreat);return;}if(a==='loot'){apply(E.collectLoot,'Relic and gold added to inventory');return;}if(a==='cell'){const x=Number(b.dataset.x),y=Number(b.dataset.y);if(b.dataset.unit?.startsWith('enemy'))apply(s=>{s.battle.selected=b.dataset.unit});else if(!b.dataset.unit)apply(s=>E.moveHero(s,x,y));return;}if(a==='inspect-place'){inspectPlace(b.dataset.place);return;}if(a==='assign-art'||a==='assign-battle-art'){const asset=library.find(i=>i.id===b.dataset.art);if(!asset)throw Error('Unknown image.');apply(s=>{const field=a==='assign-art'?'artAssignments':'battleArtAssignments';s[field]||={};s[field][s.location]=asset.id;E.log(s,'Assigned artwork '+fixLabel(asset.label)+' at '+current().name,'story');});closeModal();toast('Artwork assigned; original file preserved.');return;}if(a==='inspect-art'){const art=library.find(i=>i.id===b.dataset.art);showModal(`<span class="eyebrow">Original artwork · ${esc(art.category)}</span><h2>${esc(fixLabel(art.label))}</h2><img class="modal-art" src="${art.path}" alt="${esc(fixLabel(art.label))}"><p class="muted">Preserved from ${esc(art.sourceArchive.split(/[\\/]/).at(-1))}. Original names and image contents retained.</p><small>Asset ID: ${art.id}</small><div class="secondary-actions">${button('Use in this scene','assign-art',`data-art="${art.id}"`,'primary')}${button('Use as encounter backdrop','assign-battle-art',`data-art="${art.id}"`)}${button('Place on left','layer-art',`data-art="${art.id}" data-side="left"`)}${button('Place on right','layer-art',`data-art="${art.id}" data-side="right"`)}</div>`);return;}if(a==='inspect-item'){const i=ITEMS.find(i=>i.id===b.dataset.item);showModal(`<span class="eyebrow">${i.kind}</span><h2>${i.name}</h2><div class="item-illustration">${glyph[i.icon]}</div><p>${i.description}</p>`);return;}if(a==='read-book'){const book=BOOKS.find(i=>i.id===b.dataset.book);showModal(`<span class="eyebrow">The traveling library · Moonveil homebrew lore</span><h2>${book.name}</h2>${book.chapters.map(([h,t])=>`<section class="book-page"><h3>${h}</h3><p>${t}</p></section>`).join('')}`);return;}if(a==='guide-question'){chat.push({who:'you',text:b.textContent},{who:'guide',text:E.guide(state,b.dataset.question)});render();return;}if(a==='export'){download(JSON.stringify({format:'moonveil-universe-v1',savedAt:new Date().toISOString(),game:state},null,2),'moonveil-'+state.hero.name.replace(/[^a-z0-9]/gi,'-')+'.json');toast('Backup exported.');return;}
 if(a==='sound'){if(!state){toast('Create a character, then enable sound.');return;}const on=!state.sound;setAudio(on);apply(s=>s.sound=on);if(modal.open)settings();return;}if(a==='narration'){apply(s=>s.narration=!s.narration);settings();if(state.narration)speak('Your story is yours to tell.');return;}if(a==='autonomy'){apply(s=>s.autonomy=!s.autonomy);settings();return;}if(a==='toggle-companion'){apply(s=>s.companion.enabled=!s.companion.enabled);settings();return;}
 }catch(error){toast(error.message);}});
document.addEventListener('submit',event=>{if(event.target.id==='characterForm'){event.preventDefault();try{const values=Object.fromEntries(new FormData(event.target));const candidate=E.createGame({...values,className:calling});if(disk){localStorage.setItem('moonveil-universe-backup-'+Date.now(),disk);}disk=localStorage.getItem(KEY);saveCandidate(candidate);closeModal();sceneFrame=0;chat=[];render();toast('Welcome to Moonveil, '+candidate.hero.name+'.');}catch(error){toast(error.message);}}if(event.target.id==='chatForm'){event.preventDefault();const text=new FormData(event.target).get('message').trim();if(!text)return;chat.push({who:'you',text},{who:'guide',text:E.guide(state,text)});chat=chat.slice(-20);render();}});
document.addEventListener('change',event=>{if(event.target.id==='codexFilter'){codexFilter=event.target.value;render();}});
document.addEventListener('input',event=>{if(event.target.id==='referenceSearch'){referenceSearch=event.target.value;document.getElementById('referenceResults').innerHTML=referenceRows();}if(event.target.id==='codexSearch'){codexSearch=event.target.value;const start=event.target.selectionStart;render();const input=document.getElementById('codexSearch');input.focus();input.setSelectionRange(start,start);}});
document.getElementById('saveFile').addEventListener('change',async event=>{try{const file=event.target.files[0];if(!file)return;if(file.size>3_000_000)throw Error('Save file is too large.');const payload=JSON.parse(await file.text());if(payload.format!=='moonveil-universe-v1')throw Error('Use a Moonveil Universe save export. Legacy campaign saves remain separate.');const game=E.validateGame(payload.game);if(!confirm('Load '+game.hero.name+'? Your current Universe save will be backed up first.'))return;if(disk)localStorage.setItem('moonveil-universe-backup-'+Date.now(),disk);disk=localStorage.getItem(KEY);saveCandidate(game);closeModal();render();toast('Journey restored.');}catch(error){toast('Import rejected: '+error.message);}finally{event.target.value='';}});
window.addEventListener('storage',event=>{if(event.key===KEY&&event.newValue!==disk)toast('This save changed in another tab. Reload before continuing.');});

function referenceRows(){const matching=referenceRecords.filter(r=>(r.name+' '+r.category).toLowerCase().includes(referenceSearch.toLowerCase()));return matching.slice(0,40).map(r=>'<button class="reference-row" data-action="reference" data-record="'+r.id+'"><strong>'+esc(r.name)+'</strong><small>'+esc(r.category)+' · SRD 5.1</small></button>').join('')+(matching.length>40?'<p class="muted">'+matching.length+' matches. Search to narrow the list.</p>':'');}
function referenceShelf(){return '<section class="section-divider"><span class="eyebrow">The reference library</span><h2>Spells, creatures & magic items.</h2><p class="muted">'+referenceRecords.length+' source entries from the SRD 5.1 archive. Readable references are separate from automated game actions.</p><input id="referenceSearch" aria-label="Search rules reference" placeholder="Find a spell, creature, magic item or ancestry…" value="'+esc(referenceSearch)+'"><div id="referenceResults" class="reference-grid">'+referenceRows()+'</div>'+button('SRD attribution & license','reference-legal')+'</section>';}
function assistantHelp(){showModal('<span class="eyebrow">One table · You and your guide</span><h2>Play together.</h2><p>Keep this game open in the app browser and talk to ChatGPT in this chat. You can ask: “Read my current game,” “Move me to Lanternfall,” “Play the enemies,” or “Narrate this scene.”</p><p>The page exposes validated game controls to the assistant when this browser supports them. Start the app’s voice mode to talk hands-free. Spoken website narration can read dialogue aloud.</p><div class="notice">The built-in Wayfinder is a scripted guide. A separate generative AI service and a multiplayer server are not running inside this website.</div>');}
function listen(){const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition){toast('Voice input is not supported in this browser. Use the app’s voice mode or type your message.');return;}const recognition=new Recognition();recognition.lang='en-US';recognition.interimResults=false;recognition.onresult=e=>{const input=document.querySelector('#chatForm input');if(input){input.value=e.results[0][0].transcript;input.focus();toast('Voice captured. Review and send your message.');}};recognition.onerror=()=>toast('Voice input was unavailable. You can still type or use the app’s voice mode.');recognition.start();toast('Listening…');}
function assistantAction(input){if(!input||typeof input.action!=='string'||!state)throw Error('An active character and valid action are required.');const allowed=['travel','explore','talk','accept','complete','start_combat','move','attack','end_turn','guard','companion','loot','rest','retreat','view'];if(!allowed.includes(input.action))throw Error('Unsupported game action.');apply(s=>{switch(input.action){case'travel':E.travel(s,input.destination);break;case'explore':E.explore(s);break;case'talk':E.talk(s);break;case'accept':E.acceptQuest(s,input.questId);break;case'complete':E.completeQuest(s,input.questId);break;case'start_combat':E.beginBattle(s);break;case'move':if(!Number.isInteger(input.x)||!Number.isInteger(input.y))throw Error('Grid coordinates must be integers.');E.moveHero(s,input.x,input.y);break;case'attack':if(!['bolt','melee'].includes(input.kind))throw Error('Choose bolt or melee.');E.attack(s,input.targetId,input.kind);break;case'end_turn':E.endTurn(s);break;case'guard':E.guard(s);break;case'companion':E.companionAct(s);break;case'loot':E.collectLoot(s);break;case'rest':E.rest(s);break;case'retreat':E.retreat(s);break;case'view':if(!['journey','atlas','character','inventory','codex','guide','battle','life'].includes(input.view))throw Error('Unknown view');s.view=input.view;}});return{ok:true,hero:state.hero,location:state.location,quests:state.quests,battle:state.battle,latestEvent:state.events[0]};}

function assignArtwork(input){if(!state||!input||typeof input.locationId!=='string'||!PLACES.some(p=>p.id===input.locationId)||!library.some(a=>a.id===input.assetId)||!['scene','battle'].includes(input.slot))throw Error('Choose a known location, verified asset ID and scene or battle slot.');apply(s=>{const key=input.slot==='battle'?'battleArtAssignments':'artAssignments';s[key]||={};s[key][input.locationId]=input.assetId;E.log(s,'DM assigned '+input.assetId+' to '+input.locationId+' ('+input.slot+').','story');});return{ok:true,location:input.locationId,assetId:input.assetId,slot:input.slot};}
function dmUpdate(input){if(!state||!input||typeof input.note!=='string'||!input.note.trim()||input.note.length>500)throw Error('A DM adjustment needs a note, up to 500 characters.');const changes=input.changes;if(!changes||typeof changes!=='object'||Array.isArray(changes))throw Error('Provide a changes object.');const allowed=['hp','gold','slots','location'];if(Object.keys(changes).some(k=>!allowed.includes(k)))throw Error('Unsupported DM field.');apply(s=>{if(changes.hp!==undefined){if(!Number.isInteger(changes.hp)||changes.hp<0||changes.hp>s.hero.maxHp)throw Error('HP is out of range.');s.hero.hp=changes.hp;if(s.battle)s.battle.units.find(u=>u.id==='hero').hp=changes.hp;}if(changes.gold!==undefined){if(!Number.isInteger(changes.gold)||changes.gold<0||changes.gold>1000000)throw Error('Gold is out of range.');s.hero.gold=changes.gold;}if(changes.slots!==undefined){if(!Number.isInteger(changes.slots)||changes.slots<0||changes.slots>s.hero.maxSlots)throw Error('Focus is out of range.');s.hero.slots=changes.slots;}if(changes.location!==undefined){if(s.battle?.status==='active'||s.loot)throw Error('Resolve the encounter before moving the campaign.');if(!PLACES.some(p=>p.id===changes.location))throw Error('Unknown location.');s.location=changes.location;if(!s.visited.includes(s.location))s.visited.push(s.location);}E.log(s,'DM adjustment: '+input.note+' · '+JSON.stringify(changes),'story');});return{ok:true,hero:state.hero,location:state.location,audit:state.events[0]};}
if(document.modelContext?.registerTool){const register=t=>{try{Promise.resolve(document.modelContext.registerTool(t)).catch(()=>{});}catch{}};register({name:'moonveil_find_art',description:'Search verified original Moonveil artwork by its original title/category, returning stable IDs for scene or battle assignment.',inputSchema:{type:'object',properties:{query:{type:'string'},category:{type:'string'}},additionalProperties:false},execute:input=>{const q=String(input?.query||'').toLowerCase(),category=String(input?.category||'');return{total:library.length,matches:library.filter(a=>(!category||a.category===category)&&fixLabel(a.label).toLowerCase().includes(q)).slice(0,35).map(a=>({id:a.id,name:fixLabel(a.label),category:a.category,url:new URL(a.path,location.href).href}))};}});register({name:'moonveil_assign_art',description:'Assign an existing verified image to a known location scene or encounter backdrop without changing the original image or player location.',inputSchema:{type:'object',properties:{locationId:{type:'string'},assetId:{type:'string'},slot:{type:'string',enum:['scene','battle']}},required:['locationId','assetId','slot'],additionalProperties:false},execute:assignArtwork});register({name:'moonveil_dm_adjust',description:'Make a logged DM adjustment to active character HP, gold, focus or known world location. Requires a human-readable reason. Preserves game validation and the event ledger.',inputSchema:{type:'object',properties:{note:{type:'string'},changes:{type:'object',properties:{hp:{type:'integer'},gold:{type:'integer'},slots:{type:'integer'},location:{type:'string'}},additionalProperties:false}},required:['note','changes'],additionalProperties:false},execute:dmUpdate});register({name:'moonveil_read_world',description:'Read the active character, connected map locations, quest stages, inventory, and tactical situation in Moonveil.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:()=>state?{hero:state.hero,location:state.location,places:PLACES,quests:state.quests,questDefinitions:QUESTS,inventory:state.inventory,battle:state.battle,companion:state.companion,profession:state.profession||null,devotion:state.devotion||{},worldFlags:state.flags}: {character:null}});register({name:'moonveil_take_action',description:'Perform one validated action on the current Moonveil game using the same rules as its visible buttons. Ask the player what they want unless they authorized you to play or control the encounter.',inputSchema:{type:'object',properties:{action:{type:'string',enum:['travel','explore','talk','accept','complete','start_combat','move','attack','end_turn','guard','companion','loot','rest','retreat','view']},destination:{type:'string'},questId:{type:'string'},targetId:{type:'string'},kind:{type:'string',enum:['bolt','melee']},view:{type:'string'},x:{type:'integer'},y:{type:'integer'}},required:['action'],additionalProperties:false},execute:assistantAction});register({name:'moonveil_narrate_scene',description:'Display narration or NPC dialogue over the current Moonveil scene. Does not change stats, inventory, quest rewards or location.',inputSchema:{type:'object',properties:{speaker:{type:'string'},text:{type:'string'}},required:['speaker','text'],additionalProperties:false},execute:input=>{if(!state||typeof input?.speaker!=='string'||typeof input?.text!=='string'||input.speaker.length>80||input.text.length>1600||!input.text.trim())throw Error('Provide a speaker and up to 1600 characters of narration.');apply(s=>{s.director={speaker:input.speaker,text:input.text};s.view='journey';E.log(s,input.speaker+': '+input.text,'story');});speak(input.text);return{ok:true,narration:state.director,location:state.location};}});}
render();

function lifeContext(){return {state,button,esc,file};}
function lifeView(){return drawLife(lifeContext());}
function cryptView(){return drawCrypt(lifeContext());}
function templePanel(p){return drawTemple(p,lifeContext());}

function worldInteraction(input){
 const actions={train:s=>L.train(s,input.id),gather:L.gather,craft:L.craft,accept_order:s=>L.acceptOrder(s,input.id),deliver:s=>L.deliver(s,input.id),pray:s=>L.templeService(s,input.id,'pray'),heal:s=>L.templeService(s,input.id,'heal'),accept_pilgrimage:L.acceptPilgrimage,complete_pilgrimage:L.claimPilgrimage,enter_room:s=>L.moveRoom(s,input.id),interact_room:L.interactRoom,cast:s=>E.castSpell(s,input.targetId,input.id),use_ward:E.useWard,inscribe_scroll:L.inscribeScroll,trace_ritual:s=>L.traceRitual(s,input.id),assisted_action:playAssistedAction};
 if(!state||!actions[input?.action])throw Error('Choose a supported world interaction.');apply(actions[input.action]);return{ok:true,location:state.location,profession:state.profession,devotion:state.devotion,flags:state.flags,hero:state.hero,battle:state.battle};
}
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'moonveil_world_interaction',description:'Use connected Moonveil profession, temple, pilgrimage, crypt-room, wardstone or homebrew spell actions under the same rules and costs as the visible buttons.',inputSchema:{type:'object',properties:{action:{type:'string',enum:['train','gather','craft','accept_order','deliver','pray','heal','accept_pilgrimage','complete_pilgrimage','enter_room','interact_room','cast','use_ward','inscribe_scroll','trace_ritual','assisted_action']},id:{type:'string'},targetId:{type:'string'}},required:['action'],additionalProperties:false},execute:worldInteraction});}catch{}}

function sceneLayers(){const layers=state.sceneLayers?.[state.location]||{};return ['left','right'].map(side=>{const a=library.find(a=>a.id===layers[side]);return a?`<div class="scene-actor actor-${side}"><img src="${a.path}" alt="Reusable foreground artwork: ${esc(fixLabel(a.label))}"><button data-action="remove-layer" data-side="${side}" aria-label="Remove ${side} foreground layer">×</button><small>${esc(fixLabel(a.label))}</small></div>`:'';}).join('');}
